/// <summary>
/// Update expiry date for sales item substitute record
/// </summary>
/// <param name = "_salesItemSubs"><c>METSalesItemSubstitute</c></param>
/// <param name = "_expiryDate"><c>TransDate</c></param>
public void updateExpiryDate(METSalesItemSubstitute _salesItemSubs, TransDate _expiryDate)
{
    TransDate               newExpiryDate, currentDate;
    METSalesItemSubstitute  currentRecord, salesItemSubstitute;

    currentDate     = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    newExpiryDate   = _expiryDate;

    select forupdate currentRecord
        where currentRecord.RecId == _salesItemSubs.RecId;

    if (currentRecord.ValidTo < currentDate)
    {
        throw error(strFmt("@MET:METItemAndSubItemExpiredError",
            currentRecord.ItemId, currentRecord.SubstituteItemId));
    }
    else if (newExpiryDate < currentRecord.ValidFrom)
    {
        throw error(strFmt(
        "@MET:METExpiryDateMustBeGreaterError",
            newExpiryDate, currentRecord.ValidFrom, currentRecord.ItemId, currentRecord.SubstituteItemId));
    }
    // Check for overlapping ranges for same item, & substitution
    // (Except current record)
    select firstonly salesItemSubstitute
        where salesItemSubstitute.RecId != currentRecord.RecId
        && salesItemSubstitute.ItemId == currentRecord.ItemId
        && salesItemSubstitute.ValidFrom <= newExpiryDate
        && salesItemSubstitute.ValidTo >= newExpiryDate;

    if (salesItemSubstitute.RecId)
    {
        throw error(strFmt(
                "@MET:METExpiryDateOverlapsError",
                newExpiryDate, salesItemSubstitute.ValidFrom, salesItemSubstitute.ValidTo, salesItemSubstitute.ItemId));
    }

    // Passed all validations — update the record
    ttsbegin;
    currentRecord.ValidTo = newExpiryDate;
    currentRecord.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);
    currentRecord.update();
    ttscommit;

    info(strFmt("@MET:METExpiryDateUpdatedInfo", newExpiryDate, currentRecord.ItemId, currentRecord.SubstituteItemId));
}

/// <summary>
/// Clicked event for Apply button
/// </summary>
public void clicked()
{ 
    Set                     recIdSet = new Set(Types::Int64);
    FormRun                 callerForm;
    TransDate               expiryDateValue;
    FormDataSource          salesItemSubstitute_ds;
    MultiSelectionHelper    selectionHelper;
    METSalesItemSubstitute  salesItemSustitue;

    super();

    expiryDateValue = ExpiryDate.dateValue();

    if (expiryDateValue != dateNull())
    {
        callerForm              = element.args().caller() as FormRun;
        salesItemSubstitute_ds  = callerForm.dataSource(formDataSourceStr(METSalesItemSubstitute, METSalesItemSubstitute));

        selectionHelper = MultiSelectionHelper::construct();
        selectionHelper.parmDatasource(salesItemSubstitute_ds);

        salesItemSustitue  = selectionHelper.getFirst();

        if (salesItemSustitue.RecId)
        {
            while (salesItemSustitue.RecId != 0)
            {
                element.updateExpiryDate(salesItemSustitue, expiryDateValue);
                salesItemSustitue = selectionHelper.getNext();
            }
        }
    }
    // Refresh caller datasource so UI shows changes
    if (salesItemSubstitute_ds)
    {
        salesItemSubstitute_ds.research(true);
        salesItemSubstitute_ds.refresh();
    }
    // Close dialog
    element.closeOk();
}
